SELECT r.id,c.id AS contest_id, r.submission_start::text AS submission_start,r.submission_end::text AS submission_end, r.zsl_vote_end::text AS zsl_vote_end,r.cosmetic_vote_end::text AS cosmetic_vote_end, coalesce((clock_timestamp()>=r.submission_start AND clock_timestamp()<r.submission_end),false) AS submissions_open, coalesce((clock_timestamp()>=r.submission_end AND clock_timestamp()<r.zsl_vote_end),false) AS zsl_open, coalesce((clock_timestamp()>=r.submission_end AND clock_timestamp()<r.cosmetic_vote_end),false) AS cosmetic_open, coalesce(clock_timestamp()>=r.zsl_vote_end,false) AS zsl_closed, coalesce(clock_timestamp()>=r.cosmetic_vote_end,false) AS cosmetic_closed, coalesce((c.state='frozen' AND c.finalized_at IS NOT NULL AND c.current_playlist_id IS NOT NULL),false) AS finalized FROM public.zsl_round r LEFT JOIN LATERAL (SELECT * FROM zc_private.level_submission_contest WHERE id_zsl_round=r.id ORDER BY id DESC LIMIT 1) c ON true WHERE ($1::integer IS NOT NULL AND r.id=$1) OR ($1::integer IS NULL AND r.submission_start<=clock_timestamp() AND r.cosmetic_vote_end>clock_timestamp()) ORDER BY r.submission_end DESC LIMIT 1
